impl DocIssue {
    pub fn line(&self) -> String {
        let level = match self.level {
            IssueLevel::Error => "error",
            IssueLevel::Warning => "warning",
        };
        match &self.element {
            Some(e) => format!("- {level} ({e}): {}", self.message),
            None => format!("- {level}: {}", self.message),
        }
    }
}

